def generate_default_observer_schema(app):
    # Initialize an empty observer schema dictionary
    observer_schema = {}

    # Iterate over all Kubernetes resources in spec.manifest
    for resource in app.spec.manifest:
        # Check if a custom observer schema has been specified for this resource
        if not resource.observer_schema:
            # If not, generate a default observer schema
            name = "observer-schema-{}".format(resource.spec.kind.lower)
            observer_schema[name] = {
                "observed_value": resource.spec.value,
                "source": [resource.metadata.name],
                "schema": {
                    "value": {
                        "type": "generic",
                        "spec": {}
